corrected_code:
const { Kafka } = require('kafkajs');
const kafka = new Kafka({ brokers: [process.env.KAFKA_BROKER] });
const consumer = kafka.consumer({ groupId: 'iot-firmware-flasher' });

async function run() {
  await consumer.connect();
  await consumer.subscribe({ topic: 'iot.device.firmware_downgrade', fromBeginning: false });

  await consumer.run({
    eachMessage: async ({ message }) => {
      const payload = JSON.parse(message.value.toString());
      const { deviceHardwareId, targetVersion, initiatedByUserId } = payload;

      const device = await Device.findOne({
        hardwareId: deviceHardwareId,
        ownerUserId: initiatedByUserId
      });
      if (!device) {
        console.error(`OTA firmware downgrade rejected: device ${deviceHardwareId} not owned by ${initiatedByUserId}`);
        return;
      }

      await mqttPublisher.publish(`devices/${deviceHardwareId}/ota`, JSON.stringify({
        action: 'FLASH_FIRMWARE',
        firmwareUrl: `https://firmware.vendor.com/v${targetVersion}.bin`
      }));
      device.currentFirmware = targetVersion;
      await device.save();
    }
  });
}
